import{_ as o,b as s,c as d,g as n,f as t}from"./chunks/framework.86O3EbG5.js";const _=JSON.parse('{"title":"约束满足问题","description":"","frontmatter":{"title":"约束满足问题","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/6.md","filePath":"articles/ai/books/ai-modern-approach/6.md"}'),i={name:"articles/ai/books/ai-modern-approach/6.md"};function p(a,r,e,g,l,h){return s(),d("div",null,[...r[0]||(r[0]=[n('<p>本章聚焦约束满足问题（CSP），是比通用搜索更高效的一种问题建模方法。核心内容：</p><p>CSP的基本要素</p><p>变量、值域、约束（一元、二元、全局）。</p><p>约束图：节点为变量，边为二元约束。</p><p>回溯搜索</p><p>深度优先+约束检测。实用改进：</p><p>变量排序：最少剩余值（MRV）、度启发式。</p><p>值排序：最少约束值（LCV）。</p><p>前向检查：赋值后从相邻变量值域中删除不合法值，提前检测失败。</p><p>约束传播</p><p>弧一致性（AC-3）：保持所有弧的二元约束满足，删除值域中无支持的值。</p><h2 id="相关概念解释" tabindex="-1">相关概念解释</h2><p>约束问题（CSP）的形式化定义：</p>',13),t("ul",null,[t("li",{"X1,...,Xn":""},"X 是变量集合，"),t("li",null,"D 是域集合，{D1,...,Dn}，每个变量有一个域"),t("li",null,"C 约束集合，用来规定允许值的组合。对应实际问题的限制条件，例如两个相邻区域色彩不能相同")],-1),n('<p>让我们用一个贯穿始终的生动例子来解释CSP中的各种概念：<strong>“动物派对排座位”</strong>。</p><p>假设你要安排<strong>大象、斑马、企鹅</strong>三只动物坐在一排三个座位上（座位1、2、3）。每个动物有喜欢的颜色（红、蓝、绿）和食物（草、鱼、肉）。问题涉及多种约束，我们逐一展开。</p><hr><h2 id="一、基本概念-离散有限域、线性-非线性约束、一元-二元-全局约束" tabindex="-1">一、基本概念：离散有限域、线性/非线性约束、一元/二元/全局约束</h2><ul><li><strong>离散有限域</strong>：每个变量的取值来自有限、可数的集合。例如大象的座位域是{1,2,3}，颜色域是{红,蓝,绿}。这就是<strong>离散</strong>且<strong>有限</strong>的。</li><li><strong>线性约束</strong>：约束可以写成变量乘以系数的线性等式或不等式。例如“大象的座位号 ≤ 斑马的座位号”（座位1≤座位2）是线性约束。</li><li><strong>非线性约束</strong>：约束涉及乘法、取模、绝对值等。例如“大象和斑马的座位号之差的绝对值 ≠ 1”（不能相邻）是非线性的（绝对值）。</li><li><strong>一元约束</strong>：只涉及单个变量。例如“企鹅不能坐座位2”。</li><li><strong>二元约束</strong>：涉及两个变量。例如“大象和斑马不能同座”。</li><li><strong>全局约束</strong>：涉及任意多个变量。例如“所有动物的座位互不相同”（Alldiff），它等价于多个二元不等约束的集合，但作为整体更高效。</li></ul><hr><h2 id="二、一致性概念-用于约束传播" tabindex="-1">二、一致性概念（用于约束传播）</h2><h3 id="_1-节点一致-node-consistency" tabindex="-1">1. 节点一致（Node Consistency）</h3><p><strong>定义</strong>：单个变量值域中的所有值都满足它的一元约束。<br><strong>例子</strong>：如果一元约束“企鹅不能坐座位2”，那么企鹅的值域{1,2,3}中需要删除2 → {1,3}。达到节点一致。</p><h3 id="_2-弧一致-arc-consistency" tabindex="-1">2. 弧一致（Arc Consistency）</h3><p><strong>定义</strong>：对每个二元约束，变量域中每个值在另一变量域中都有至少一个值使其满足约束。<br><strong>生动解释</strong>：大象和斑马有“不能同座”约束。检查大象的座位1：斑马域中要有不是1的值（有2,3）→ ok；大象座位2：斑马要有不是2的值→ ok；大象座位3：ok。反过来检查斑马也一样。如果某值找不到搭档，就删除它。<br><strong>作用</strong>：弧一致是CSP中最常用的传播技术，例如AC-3算法。</p><h3 id="_3-路径一致-path-consistency" tabindex="-1">3. 路径一致（Path Consistency）</h3><p><strong>定义</strong>：通过三元变量间的约束，检查任意一对变量在第三个变量的帮助下是否相容。<br><strong>例子</strong>：大象、斑马、企鹅三个变量。大象和斑马不能同座，斑马和企鹅不能同座，大象和企鹅没有直接约束。路径一致会检查：是否存在一个斑马的座位值，使得大象和斑马、斑马和企鹅都相容？如果不存在，则调整大象和企鹅的值域。<br><strong>比喻</strong>：通过中间人（斑马）来调节另外两个人的关系。</p><h3 id="_4-k一致-k-consistency" tabindex="-1">4. K一致（K-Consistency）</h3><p><strong>定义</strong>：对于任意K-1个变量的相容赋值，总能给第K个变量赋值使其与前面相容。<br><strong>直观</strong>：K=2就是弧一致（任意一个变量，总能找到另一个变量的值满足约束）。K=3是路径一致。<br><strong>强K一致</strong>：对于所有j≤K，都是j一致的。强K一致意味着无需回溯就能找到解（如果存在）。</p><h3 id="_5-边界传播-bound-propagation" tabindex="-1">5. 边界传播（Bound Propagation）</h3><p>用于连续域或有序域的数值约束。通过约束不等式，逐步收紧变量的上下界。<br><strong>例子</strong>：大象的座位≤斑马的座位，且大象座位≥1，斑马座位≤3。初始大象[1,3]，斑马[1,3]。传播：斑马≥大象，所以斑马下界≥大象下界；大象上界≤斑马上界。反复收紧直到稳定。</p><hr><h2 id="三、求解算法" tabindex="-1">三、求解算法</h2><h3 id="_1-回溯搜索-backtracking-search" tabindex="-1">1. 回溯搜索（Backtracking Search）</h3><p><strong>思想</strong>：深度优先搜索，每次给一个变量赋值，若违反约束则回退到上一个变量尝试其他值。<br><strong>生动例子</strong>：你依次安排大象、斑马、企鹅的座位。</p><ul><li>大象坐1。</li><li>斑马坐2（检查：与大象不同，ok）。</li><li>企鹅只能坐3（检查与斑马不同，与大象不同，ok）。找到解。</li><li>如果企鹅没位置了，就回退到斑马换座位（例如换到3），再试企鹅。<br><strong>这是CSP的最基本求解器</strong>。</li></ul><h3 id="_2-局部搜索-local-search-for-csp" tabindex="-1">2. 局部搜索（Local Search for CSP）</h3><p><strong>思想</strong>：不完整搜索，从一个完整但可能违反约束的赋值开始，通过修改变量的值（例如随机或选择冲突最小的）来逐步减少冲突数量。<br><strong>生动例子</strong>：你随便给三只动物各分配一个座位（可能冲突）。然后每次都选一个冲突最多的动物，换到另一个座位使得冲突减少。重复直到无冲突或达到时间上限。<br><strong>典型算法</strong>：最小冲突启发式（Min-Conflicts），非常高效，尤其适合大规模CSP（如百万皇后问题）。</p><hr><h2 id="总结表" tabindex="-1">总结表</h2><table tabindex="0"><thead><tr><th>概念</th><th>通俗解释</th></tr></thead><tbody><tr><td>离散有限域</td><td>变量取值像选择题，选项固定且数量有限</td></tr><tr><td>线性约束</td><td>像“我的年龄≤你的年龄”</td></tr><tr><td>非线性约束</td><td>像“我们不能相邻坐”</td></tr><tr><td>一元约束</td><td>只限制一个变量，如“企鹅不能坐1号”</td></tr><tr><td>二元约束</td><td>限制两个变量，如“大象≠斑马”</td></tr><tr><td>全局约束</td><td>同时限制多个变量，如“所有动物座位互异”</td></tr><tr><td>节点一致</td><td>把明显违规的选项删掉</td></tr><tr><td>弧一致</td><td>确保每对变量之间都有“搭档”</td></tr><tr><td>路径一致</td><td>通过第三方间接检查关系</td></tr><tr><td>K一致/强K一致</td><td>任意K个变量都能协调</td></tr><tr><td>边界传播</td><td>通过不等式收紧取值范围</td></tr><tr><td>回溯搜索</td><td>尝试赋值，碰壁就回退</td></tr><tr><td>局部搜索</td><td>从乱分配开始，逐步改到无冲突</td></tr></tbody></table><p>希望这个“动物派对”的例子能让你轻松记住CSP的核心概念。如果你需要进一步讲解某个算法的伪代码或实现细节，随时告诉我。</p><h2 id="为什么介绍-csp" tabindex="-1">为什么介绍 CSP</h2><p>之前的搜索算法依赖于特定领域迭代启发算法进行状态空间的搜索，然后我认为并不是每个人都能成为问题领域的专家，所以要发明一种 不依赖于领域专家的解决问题的思路，所以需要通用的启发式算法，CSP就是这样一种通用的启发式算法。</p><p>CSP的结构</p><p>树形CSP：可在线性时间求解（通过拓扑排序+方向弧一致）。</p><p>树分解：将一般CSP转化为树形子问题（降低复杂度）。</p><p>局部搜索</p><p>最小冲突法：随机初始解，迭代减少冲突，常用于大规模CSP（如N皇后）。</p>',35)])])}const b=o(i,[["render",p]]);export{_ as __pageData,b as default};
